namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly object _lock = new();

    public Task<List<NotificationItem>> GetInitialNotificationsAsync()
    {
        var notifications = new List<NotificationItem>
        {
            new() { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
            new() { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
            new() { Id = _nextId++, Message = "New feature available: dark mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) },
        };
        return Task.FromResult(notifications);
    }

    public Task<List<NotificationItem>> CheckForNewNotificationsAsync(int afterId)
    {
        // Simulate sporadic new notifications
        lock (_lock)
        {
            var items = new List<NotificationItem>();
            if (Random.Shared.Next(0, 3) == 0) // ~33% chance each poll
            {
                items.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = $"New event at {DateTime.UtcNow:HH:mm:ss}",
                    Timestamp = DateTime.UtcNow
                });
            }
            return Task.FromResult(items);
        }
    }
}

@page "/notifications"
@rendermode @(new InteractiveServerRenderMode(prerender: true))
@implements IDisposable
@inject NotificationsApp.Services.NotificationService NotificationService

<PageTitle>Notifications</PageTitle>

<h1>Notifications <span class="badge bg-primary">@_notifications.Count</span></h1>

<ul class="list-group">
    @foreach (var n in _notifications.OrderByDescending(x => x.Timestamp))
    {
        <li class="list-group-item">
            <strong>@n.Message</strong>
            <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
        </li>
    }
</ul>

@code {
    private List<NotificationsApp.Services.NotificationItem> _notifications = new();
    private CancellationTokenSource? _cts;
    private bool _isInteractive;

    protected override async Task OnInitializedAsync()
    {
        // Runs during prerender AND when the component becomes interactive.
        // Only load from service on the first call (prerender).
        if (_notifications.Count == 0)
        {
            _notifications = await NotificationService.GetInitialNotificationsAsync();
        }
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender && !_isInteractive)
        {
            // OnAfterRender only fires when truly interactive (not during static SSR).
            _isInteractive = true;
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);

                var lastId = _notifications.Count > 0 ? _notifications.Max(n => n.Id) : 0;
                var newItems = await NotificationService.CheckForNewNotificationsAsync(lastId);

                if (newItems.Count > 0)
                {
                    _notifications.AddRange(newItems);
                    await InvokeAsync(StateHasChanged);
                }
            }
            catch (TaskCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

